    const union r_tdl_u *r_ru = &r_tdl_r[(r_t >> 19) & 127u]; /* R4rv: (t >> 19) - 0xFA0 = ((t >> 19) & 127) - 32 */
    const struct r_rx_r *r_r = &r_ru[-32].r_l;
