    r_c0v_ = r_r->r_c0 - 0x100u; /* R4res: the c0 the cell has just read */
    r_ts_ = r_w << 13; /* R4res: set by the caller (the cells' own offset register) */ r_GO_SCELL_r(126, (r_V >> 9) + 0x800000u, 1u, 0u, 0, r_scellp_); /* (X >> 9 = (V >> 9) - 1 on a decline) */
