    const struct r_rx_r *r_r = &r_tdl_r[(r_t >> 19) - 3872u].r_l; /* R4res: tl2_r[(t >> 19) & 31] = tdl_r[224 + (t >> 19) - 0x1000] (t in [2^31, 2^31 + 2^24)) */
    uint32_t r_U = r_rxu_cell_r(r_r, r_w << 14);
